INSERT INTO `clases` (`id`, `Nombre`, `short_desc`, `descr`, `rasgos_clase`, `image_path`) VALUES
(1, 'Barbaro', 'Para algunos, su rabia brota de la comunión con espíritus de animales salvajes. Otros recurren a su hirviente reserva de ira. Para los bárbaros, la furia es un poder que no sólo les proporciona un frenesí ciego en la batalla, sino también extraordinarios reflejos, resistencia y proezas de fuerza.', 'Para algunos, su rabia brota de la comunión con espíritus de animales salvajes. Otros recurren a su hirviente reserva de ira frente a un mundo lleno de dolor. Para los bárbaros, la furia es un poder que no sólo les proporciona un frenesí ciego en la batalla, sino también extraordinarios reflejos, resistencia y proezas de fuerza.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>El Bárbaro obtiene las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Defensa sin armadura</h5>\r\n  <p>Mientras no llevas la armadura, tu CA es igual a 10 + tu modificador por Destreza + tu modificador por Constitución. Sigues pudiendo utilizar escudo y recibir sus beneficios.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Furia</h5>\r\n  <p>Puedes entrar en furia como acción adicional. Consigues ventaja en las pruebas y TS de Fuerza. Al hacer ataques cuerpo a cuerpo usando Fuerza, consigues un bonificador al daño. Tienes resistencia al daño contundente, perforante y cortante. No puedes lanzar conjuros ni concentrarte.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ataque temerario (Nivel 2)</h5>\r\n  <p>Cuando ataques por primera vez en tu turno, puedes hacer un ataque temerario, que, durante ese turno, te da ventaja en las tiradas de ataque con armas cuerpo a cuerpo utilizando Fuerza, pero, a cambio, las tiradas de ataque que se hagan contra ti tienen ventaja hasta tu siguiente turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Sentido del peligro (Nivel 2)</h5>\r\n  <p>Tienes ventaja en las tiradas de salvación de Destreza contra efectos que puedes ver, como trampas y conjuros. Para conseguir este beneficio, no puedes estar cegado, ensordecido ni incapacitado.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4, y de nuevo en los niveles 8, 12, 16 y 19, puedes aumentar una característica de tu elección en 2 o dos características en 1. Como siempre, no puedes aumentar la puntuación de una característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ataque adicional (Nivel 5)</h5>\r\n  <p>Puedes atacar dos veces en lugar de una cuando realices la acción de ataque en tu turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Movimiento rápido (Nivel 5)</h5>\r\n  <p>Tu velocidad aumenta en 10 pies mientras no lleves armadura pesada.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Instinto salvaje (Nivel 7)</h5>\r\n  <p>Tus instintos están tan pulidos que tienes ventaja en las tiradas de iniciativa. Además, si estás sorprendido al principio del combate pero no incapacitado, puedes actuar con normalidad en tu primer turno si entras en furia antes de hacer cualquier otra cosa.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Crítico brutal (Nivel 9)</h5>\r\n  <p>Puedes tirar dados adicionales de daño del arma cuando determines el daño adicional de un golpe crítico con un ataque cuerpo a cuerpo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Furia implacable (Nivel 11)</h5>\r\n  <p>Si tus puntos de golpe se reducen a 0 mientras estás en furia y no mueres inmediatamente, puedes hacer una tirada de salvación de Constitución CD 10. Si tienes éxito, te quedas con 1 punto de golpe. Cada vez que uses este rasgo después de la primera antes de un descanso, la CD aumenta en 5.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Furia persistente (Nivel 15)</h5>\r\n  <p>Tu furia es tan fiera que solo acaba antes de un minuto si caes inconsciente o si tú lo decides.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Poder indomable (Nivel 18)</h5>\r\n  <p>Si el resultado total de una prueba de Fuerza es menor que tu puntuación de Fuerza, puedes usar esa puntuación en su lugar.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Campeón primordial (Nivel 20)</h5>\r\n  <p>Encarnas el poder de la naturaleza salvaje. Tus puntuaciones de Fuerza y de Constitución aumentan en 4. El máximo de estas puntuaciones es ahora 24.</p>\r\n</div>\r\n', ''),
(2, 'Bardo', 'Ya sea un erudito, un poeta o un canalla, un bardo teje su magia a través de sus palabras y su música para inspirar a los aliados, desmoralizar a los enemigos, manipular mentes, crear ilusiones e incluso sanar heridas.', 'Ya sea un erudito, un poeta o un canalla, un bardo teje su magia a través de sus palabras y su música para inspirar a los aliados, desmoralizar a los enemigos, manipular mentes, crear ilusiones e incluso sanar heridas.\r\n', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>Obtienes las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Inspiración bárdica</h5>\r\n  <p>Usa una acción adicional otorga un dado de inspiración de bardo a una criatura a menos de 60 pies. En los 10 minutos siguientes, puede sumar el dado a una prueba de característica, tirada de ataque o TS. Puedes usarlo tantas veces como tu mod. de Carisma (mínimo 1) / descanso largo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento de conjuros</h5>\r\n  <p>Puedes lanzar conjuros utilizando tu Carisma. Al subir de nivel conoces más conjuros que puedes lanzar. Para lanzar un conjuro debes conocerlo y gastar un espacio de conjuro igual al nivel de conjuro o superior (salvo trucos). Puedes utilizar lanzamiento ritual. Puedes usar un instrumento como foco.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Aprendiz de mucho (Nivel 2)</h5>\r\n  <p>Puedes añadir la mitad de tu bonificador por competencia (redondeando hacia abajo) a cualquier prueba de característica que realices y que no lo incluya ya.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Canción de descanso (Nivel 2)</h5>\r\n  <p>Tocas música o un recital relajante para ayudar a tus aliados heridos durante un descanso breve. Si tú o cualquier criatura amistosa que pueda escuchar tu interpretación gasta uno o más dados de golpe al final del descanso para recuperar puntos de golpe, recuperáis puntos de golpe adicionales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Pericia (Nivel 3)</h5>\r\n  <p>Elige dos de tus competencias en habilidades. Tu bonificador por competencia se duplica para cualquier prueba de habilidad que utilice cualquiera de las competencias elegidas.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4, y de nuevo en los niveles 8, 12, 16 y 19, puedes aumentar una puntuación de característica de tu elección en 2 o dos puntuaciones de característica en 1. Como siempre, no puedes aumentar tu puntuación de característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Fuente de inspiración (Nivel 5)</h5>\r\n  <p>Recuperas todos los usos de tu inspiración de bardo cuando acabes un descanso breve o prolongado.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Contraencantamiento (Nivel 6)</h5>\r\n  <p>Puedes usar una acción para empezar una actuación que dura hasta el final de tu siguiente turno. Durante ese tiempo, cualquier criatura amistosa que se encuentre dentro de un radio de 30 pies y tú tenéis ventaja en cualquier TS para no quedar asustados o hechizados.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Secretos mágicos (Nivel 10)</h5>\r\n  <p>A nivel 10, 14 y 18 elige dos conjuros de cualquier clase, incluyendo esta, que sean bien un truco, bien un conjuro de un nivel que puedas lanzar. Estos conjuros cuentan como conjuros de bardo y se incluyen en el número de conjuros conocidos.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Inspiración superior (Nivel 20)</h5>\r\n  <p>Cuando tires iniciativa y no te quede inspiración de bardo, recuperas un uso.</p>\r\n</div>\r\n', ''),
(3, 'Brujo', 'Los brujos son buscadores del conocimiento que se encuentra escondido en el multiverso. A través de pactos hechos con seres poderosos de poder sobrenatural, los brujos desatan efectos mágicos tanto sutiles como espectaculares y recolectan secretos arcanos para potenciar su propio poder.', 'Los brujos son buscadores del conocimiento que se encuentra escondido en el multiverso. A través de pactos hechos con seres poderosos de poder sobrenatural, los brujos desatan efectos mágicos tanto sutiles como espectaculares y recolectan secretos arcanos para potenciar su propio poder.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>El brujo obtiene las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Magia del pacto</h5>\r\n  <p>Puedes lanzar conjuros utilizando tu Carisma. Aprendes nuevos conjuros al subir de nivel. Para lanzar un conjuro debes conocerlo y gastar un espacio de conjuro (salvo trucos). Recuperas los espacios de conjuro gastados al terminar un descanso corto o largo. Puedes usar un foco arcano.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Invocaciones sobrenaturales (Nivel 2)</h5>\r\n  <p>Mientras estudiabas el saber oculto, has descubierto invocaciones sobrenaturales, fragmentos de conocimiento prohibido que te imbuyen con una capacidad mágica duradera. En el nivel 2, consigues dos invocaciones sobrenaturales de tu elección (las opciones se detallan al final de la descripción de clase).</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Don del pacto (Nivel 3)</h5>\r\n  <p>En el nivel 3, tu patrón te otorga un don por tu leal servicio. Consigues uno de los siguientes rasgos de tu elección.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4, y de nuevo en los niveles 8, 12, 16 y 19, puedes aumentar una puntuación de característica de tu elección en 2 o dos puntuaciones de característica en 1. Como siempre, no puedes aumentar una puntuación de característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Arcano místico (Nivel 11)</h5>\r\n  <p>Tu patrón te otorga un secreto mágico llamado «arcano». Elige un conjuro del nivel indicado de la lista de conjuros de brujo como este arcano. Puedes lanzarlo una vez sin gastar un espacio de conjuro. Debes terminar un descanso prolongado para poder utilizarlo de nuevo. En niveles superiores, consigues más arcanos.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Maestro sobrenatural (Nivel 20)</h5>\r\n  <p>En el nivel 20, puedes usar tu reserva interna de poder místico cuando le implores a tu patrón para recuperar los espacios de conjuro gastados. Puedes dedicar 1 minuto a implorar ayuda a tu patrón para recuperar todos los espacios de conjuro que hayas gastado de tu rasgo Magia del pacto. Una vez que usas este rasgo, no puedes volver a usarlo hasta terminar un descanso largo.</p>\r\n</div>\r\n', ''),
(4, 'Clerigo', 'Los clérigos son intermediarios entre el mundo mortal y los distantes planos divinos. Tan diferentes entre ellos como los dioses a los que sirven, los clérigos se esfuerzan por personificar las obras de sus deidades. No son sacerdotes ordinarios, un clérigo se encuentra imbuido de magia divina.', 'Los clérigos son intermediarios entre el mundo mortal y los distantes planos divinos. Tan diferentes entre ellos como los dioses a los que sirven, los clérigos se esfuerzan por personificar las obras de sus deidades. No son sacerdotes ordinarios, un clérigo se encuentra imbuido de magia divina.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>El clérigo obtiene las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Dominio divino</h5>\r\n  <p>Sigues uno de los dominios de tu elección entre el dominio de la vida, el del descubrimiento, el de la conquista, el de lo salvaje, el del sol, el de la oscuridad y el de la prosperidad (detallados al final de la descripción de esta clase), que te otorga conjuros de dominio y otros rasgos a partir del nivel 1.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento de conjuros</h5>\r\n  <p>Puedes lanzar conjuros de clérigo utilizando tu Sabiduría. Prepara tantos conjuros como tu mod. de Sab + tu nivel de clérigo durante un descanso largo. Para lanzar un conjuro debe estar previamente preparado y gastar un espacio de conjuro igual al nivel de conjuro o superior (salvo trucos).</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento ritual</h5>\r\n  <p>Puedes lanzar cualquier conjuro de clérigo como si fuera un ritual si dicho conjuro tiene la etiqueta «ritual» y lo tienes preparado.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Canalizar divinidad (Nivel 2)</h5>\r\n  <p>Puedes canalizar la energía divina de tu deidad. Puedes expulsar muertos vivientes o realizar un efecto determinado por tu dominio. Los usos se recuperan tras un descanso breve o largo. La CD de las TS de los efectos de Canalizar Divinidad es igual a la CD de salvación de tus conjuros de clérigo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Expulsar muertos vivientes (Nivel 2)</h5>\r\n  <p>Puedes usar Canalizar divinidad para expulsar a los muertos vivientes. Como acción, presentas tu símbolo sagrado y dices una oración. Cada muerto que te vea o te escuche en un radio de 30 pies debe hacer una TS de Sabiduría. Una criatura expulsada debe dedicar su turno a intentar alejarse de ti.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando llegues al nivel 4, y de nuevo en el nivel 8, 12, 16 y 19, puedes aumentar el valor de una característica de tu elección en 2 o el valor de dos características en 1. Como siempre, no puedes aumentar el valor de una característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Destruir muertos vivientes (Nivel 5)</h5>\r\n  <p>Cuando un muerto viviente falle su tirada de salvación contra tu rasgo de Expulsar muertos vivientes, la criatura se destruirá instantáneamente si su valor de desafío es igual o inferior al umbral siguiente.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Intercesión divina (Nivel 10)</h5>\r\n  <p>Solicita a tu deidad que interceda por ti en momentos de gran necesidad. Describe el tipo de ayuda que necesitas y tira 1d100. Con un resultado igual o inferior a tu nivel de clérigo, tu deidad intercederá. El DM decide la naturaleza de la intercesión. A nivel 20 tu petición tiene éxito siempre.</p>\r\n</div>\r\n', ''),
(5, 'Druida', 'Invocando a las fuerzas elementales o emulando a las criaturas del mundo animal, los druidas son la personificación de la resistencia, astucia y furia de la naturaleza. Dicen no tener un dominio sobre la naturaleza. En lugar de eso, se ven como una extensión de la voluntad indomable de la misma.', 'Ya sea invocando a las fuerzas elementales o emulando a las criaturas del mundo animal, los druidas son la personificación de la resistencia, astucia y furia de la naturaleza. Dicen no tener un dominio sobre la naturaleza. En lugar de eso, se ven como una extensión de la voluntad indomable de la misma.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>El druida obtiene las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Druídico</h5>\r\n  <p>Conoces el druídico, el idioma secreto de los druidas. Puedes hablarlo y usarlo para dejar mensajes ocultos. Los que lo conozcáis advertís inmediatamente su presencia. Los demás deben superar una prueba de Sabiduría (Percepción) CD 15 para detectarlos, pero necesitan magia para descifrarlos.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento de conjuros</h5>\r\n  <p>Utilizando la esencia divina de la naturaleza, puedes lanzar conjuros para darle forma de acuerdo a tu voluntad. Tu característica para lanzar conjuros es la Sabiduría. Debes preparar los conjuros a lanzar tras un descanso largo. Puedes lanzar conjuros preparados que lo permitan como rituales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Forma salvaje (Nivel 2)</h5>\r\n  <p>Dos veces por descanso breve o prolongado, puedes usar tu acción para asumir mágicamente la forma de una bestia que hayas visto antes durante tantas horas como la mitad de tu nivel de druida (redondeando hacia abajo). Vuelves a tu forma como acción adicional en tu turno, si tus PG caen a 0 o mueres.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4, y de nuevo en los niveles 8, 12, 16 y 19, puedes aumentar una puntuación de característica de tu elección en 2 o dos puntuaciones de característica en 1. Como siempre, no puedes aumentar una puntuación de característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Conjuros de bestia (Nivel 18)</h5>\r\n  <p>A partir del nivel 18, puedes lanzar muchos de tus conjuros de druida en cualquier forma que asumas usando Forma salvaje. Puedes utilizar los componentes somáticos y verbales de un conjuro de druida mientras estás en forma de bestia, pero no puedes prescindir de los componentes materiales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Cuerpo eterno (Nivel 18)</h5>\r\n  <p>A partir del nivel 18, la magia primaria que usas hace que envejezcas más despacio. Por cada 10 años que pasan, tu cuerpo solo envejece 1.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Archidruida (Nivel 20)</h5>\r\n  <p>En el nivel 20 puedes usar Forma salvaje un número ilimitado de veces. Además, puedes ignorar los componentes verbales y somáticos de tus conjuros de druida, así como cualquier componente material que carezca de coste y que no se consuma al lanzar el conjuro. Tienes este beneficio tanto en tu forma normal como en Forma salvaje.</p>\r\n</div>\r\n', ''),
(6, 'Explorador', 'Lejos del bullicio de las ciudades y pueblos, más allá de las defensas que mantienen a las granjas más lejanas protegidas de los terrores de la naturaleza, en medio de tupidos bosques sin caminos y a través de enormes y vacías llanuras, los exploradores mantienen su interminable guardia.', 'Lejos del bullicio de las ciudades y pueblos, más allá de las defensas que mantienen a las granjas más lejanas protegidas de los terrores de la naturaleza, en medio de tupidos bosques sin caminos y a través de enormes y vacías llanuras, los exploradores mantienen su interminable guardia.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>El explorador obtiene las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Enemigo predilecto</h5>\r\n  <p>En los niveles 1, 6 y 14 eliges un enemigo predilecto. Tienes ventaja en las pruebas de Sabiduría (Supervivencia) para rastrear a tus enemigos predilectos, así como en las pruebas de Inteligencia para recordar información sobre ellos. También aprendes un idioma a tu elección que hablen tus enemigos.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Explorador de la naturaleza</h5>\r\n  <p>En los niveles 1, 6 y 10 consigues un terreno predilecto. Al hacer una prueba de Inteligencia o Sabiduría relacionada con uno de ellos, tu bonus de competencia se duplica. Al viajar una hora o más por ellos, consigues ventajas adicionales: sin penalización por terreno difícil, no te pierdes y más.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Estilo de combate (Nivel 2)</h5>\r\n  <p>En el nivel 2 adoptas uno de los siguientes estilos de combate como tu especialidad. No puedes coger la misma opción más de una vez, ni siquiera si más adelante se te da de nuevo la oportunidad de elegir.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento de conjuros (Nivel 2)</h5>\r\n  <p>Has aprendido cómo usar la esencia mágica de la naturaleza para lanzar conjuros, del mismo modo que lo hacen los druidas. Tu característica para lanzar conjuros es la Sabiduría. Aprendes nuevos conjuros al subir de nivel. Para lanzar un conjuro debes conocerlo y gastar un espacio de conjuro.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Conciencia primigenia (Nivel 3)</h5>\r\n  <p>Puedes usar tu acción y gastar un espacio de conjuro de explorador. Durante 1 minuto/nivel de conjuro, puedes sentir si estas criaturas están presentes a menos de 1 milla de ti (o 6 millas en terreno predilecto): aberraciones, celestiales, dragones, elementales, fatas, infernales y no muertos.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4, y de nuevo en los niveles 8, 12, 16 y 19, puedes aumentar una puntuación de característica de tu elección en 2 o dos puntuaciones de característica en 1. Como siempre, no puedes aumentar una puntuación de característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ataque adicional (Nivel 5)</h5>\r\n  <p>Puedes atacar dos veces en lugar de una cuando realices una acción de ataque durante tu turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Zancada de la tierra (Nivel 8)</h5>\r\n  <p>Sin penalización por moverte por terreno difícil no mágico. Puedes pasar por plantas no mágicas sin penalización y sin recibir daño de ellas si tienen pinchos, espinas o un peligro similar. Tienes ventaja en TS contra plantas que han sido creadas o manipuladas mágicamente para impedir el movimiento.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Esconderse a plena vista (Nivel 10)</h5>\r\n  <p>Puedes dedicar 1 minuto a crear un camuflaje si tienes acceso a barro fresco, tierra, plantas, hollín u otros materiales naturales e intentar esconderte pegándote contra una superficie sólida, como un árbol o un muro. Consigues un bonificador de +1 a Sigilo si estás sin moverte o realizar acciones.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Desaparecer (Nivel 14)</h5>\r\n  <p>Puedes usar la acción de esconderte como acción adicional durante tu turno. Asimismo, no te pueden rastrear mediante magia, a menos que decidas dejar un rastro.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Sentidos salvajes (Nivel 18)</h5>\r\n  <p>Cuando atacas a una criatura que no puedes ver, esa incapacidad no impone una desventaja a tus tiradas de ataque contra dicha criatura. También sabes dónde se encuentra cualquier criatura invisible a menos de 30 pies de ti, si la criatura no se está escondiendo y no estás cegado o ensordecido.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Asesino de enemigos (Nivel 20)</h5>\r\n  <p>Una vez por turno, puedes sumar tu modificador por Sabiduría a la tirada de ataque o a la tirada de daño que hagas contra uno de tus enemigos predilectos. Puedes usar este rasgo antes o después de hacer la tirada, pero no después de que se apliquen sus efectos.</p>\r\n</div>\r\n', ''),
(7, 'Guerrero', 'Todos los guerreros comparten un dominio magistral de las armas y armaduras, y un exhaustivo conocimiento de las habilidades del combate. Además, están muy relacionados con la muerte, tanto repartiéndola como mirándola fijamente, desafiantes.', 'Todos los guerreros comparten un dominio magistral de las armas y armaduras, y un exhaustivo conocimiento de las habilidades del combate. Además, están muy relacionados con la muerte, tanto repartiéndola como mirándola fijamente, desafiantes.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>Como guerrero, tienes las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Estilo de combate</h5>\r\n  <p>Adoptas un estilo de combate particular como tu especialidad. Escoge una de las siguientes opciones. No puedes coger la misma opción más de una vez, ni siquiera si más adelante se te da de nuevo la oportunidad de elegir.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Tomar aliento</h5>\r\n  <p>Durante tu turno, puedes usar una acción adicional para recuperar un número de puntos de golpe igual a 1d10 + tu nivel de guerrero. Una vez usas este rasgo, debes terminar un descanso corto o largo antes de poder usarlo otra vez.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Acción súbita (Nivel 2)</h5>\r\n  <p>Puedes esforzarte más allá de tus límites habituales durante un momento. En tu turno, puedes realizar una acción más aparte de tu acción normal y acción adicional habituales. Una vez uses este rasgo, debes completar un descanso corto o largo antes de poder usarlo otra vez.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4, y de nuevo en los niveles 6, 8, 12, 14, 16 y 19, puedes aumentar una puntuación de característica de tu elección en 2 o dos puntuaciones de característica en 1. Como siempre, no puedes aumentar una puntuación de característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ataque adicional (Nivel 5)</h5>\r\n  <p>Puedes atacar más de una vez cuando realices la acción de ataque durante tu turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Indomable (Nivel 9)</h5>\r\n  <p>Puedes repetir las tiradas de salvación que falles, aunque debes usar el nuevo resultado. No puedes volver a usar este rasgo hasta que no acabes un descanso prolongado.</p>\r\n</div>\r\n', ''),
(8, 'Hechicero', 'Los hechiceros tienen una magia innata, conferida por una línea de sangre exótica, una influencia de otro mundo o la exposición a fuerzas cósmicas desconocidas. Uno no puede estudiar hechicería como quien estudia un lenguaje. Nadie elige la hechicería, el poder elige al hechicero.', 'Los hechiceros tienen una magia innata, conferida por una línea de sangre exótica, una influencia de otro mundo o la exposición a fuerzas cósmicas desconocidas. Uno no puede estudiar hechicería como quien estudia un lenguaje, más de lo que uno puede aprender a vivir una vida legendaria. Nadie elige la hechicería, el poder elige al hechicero.\r\n\r\n', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>Como hechicero, obtienes las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento de conjuros</h5>\r\n  <p>Estás infundido con magia arcana que alimenta tus conjuros. Puedes lanzar conjuros arcanos utilizando tu Carisma. Aprendes nuevos conjuros al subir de nivel. Para lanzar un conjuro debes conocerlo y gastar un espacio de conjuro de nivel igual o superior (salvo trucos). Puedes usar un foco arcano.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Crear espacios de conjuro (Nivel 2)</h5>\r\n  <p>Como acción adicional, puedes transformar puntos de hechicería que no hayas gastado en un espacio de conjuro. El coste es 2 puntos para espacio de nivel 1, 3 puntos para nivel 2, 5 puntos para nivel 3, 6 puntos para nivel 4 y 7 puntos para nivel 5.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Fuente de magia (Nivel 2)</h5>\r\n  <p>Obtienes un número de puntos de hechicería igual a tu nivel de hechicero. Recuperas todos los puntos de hechicería gastados cuando terminas un descanso prolongado. En ningún caso puedes tener más puntos de hechicería de los que se indican para tu nivel.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Recuperar puntos de hechicería (Nivel 2)</h5>\r\n  <p>En tu turno, como acción adicional, puedes gastar un espacio de conjuro y conseguir tantos puntos de hechicería como el nivel del espacio.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Metamagia (Nivel 3)</h5>\r\n  <p>Consigues la capacidad de moldear tus conjuros para que se ajusten a tus necesidades. Solo puedes usar la opción de Metamagia en un conjuro cuando lo lances, salvo que se indique lo contrario. A nivel 3, consigues dos opciones de metamagia. Consigues una más a nivel 10 y otra a nivel 17.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4 y de nuevo en los niveles 8, 12, 16 y 19, puedes aumentar una puntuación de característica de tu elección en 2 o dos puntuaciones de característica en 1. Como siempre, no puedes aumentar una puntuación de característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Restablecimiento sortílego (Nivel 20)</h5>\r\n  <p>Cuando termines un descanso breve, recuperas 4 puntos de sortilegio que hayas gastado.</p>\r\n</div>\r\n', ''),
(9, 'Mago', 'Los magos son los practicantes supremos de la magia, definidos y unidos como una clase por los hechizos que conjuran. A partir de la sutil onda de la magia que impregna el cosmos, los magos lanzan explosivos hechizos de fuego, arcos voltaicos, sutiles engaños y brutales formas de control mental.', 'Los magos son los practicantes supremos de la magia, definidos y unidos como una clase por los hechizos que conjuran. A partir de la sutil onda de la magia que impregna el cosmos, los magos lanzan explosivos hechizos de fuego, arcos voltaicos, sutiles engaños y brutales formas de control mental.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>Como mago, consigues las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento de conjuros</h5>\r\n  <p>Puedes lanzar conjuros arcanos utilizando tu Inteligencia. Tienes un libro de conjuros con los conjuros que conoces, excepto los trucos, que conoces de memoria. Prepara tantos conjuros como tu modificador de Inteligencia + tu nivel de mago. Para lanzar un conjuro debes gastar un espacio de conjuro (salvo trucos).</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento ritual</h5>\r\n  <p>Puedes lanzar cualquier conjuro de mago como si fuera un ritual si tiene la etiqueta «ritual» y si lo tienes en tu libro de conjuros. No necesitas tener el conjuro preparado.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Recuperación arcana</h5>\r\n  <p>Una vez por día, cuando hagas un descanso breve, puedes recuperar espacios de conjuro con un nivel combinado igual o menor que la mitad de tu nivel de mago (redondeando hacia arriba) y, como máximo, nivel 5. Por ejemplo, si eres mago de nivel 4, puedes recuperar 2 niveles de conjuro.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>Cuando alcanzas el nivel 4 y de nuevo en los niveles 8, 12, 16 y 19, puedes aumentar una puntuación de característica de tu elección en 2 o dos puntuaciones de característica en 1. Como siempre, no puedes aumentar una puntuación de característica por encima de 20 usando este rasgo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Maestría con conjuros (Nivel 18)</h5>\r\n  <p>Elige un conjuro de mago de nivel 1 y otro de nivel 2 que estén en tu libro de conjuros. Puedes lanzarlos a su menor nivel sin gastar un espacio de conjuro cuando los tengas preparados. Para lanzarlos a un nivel superior, debes gastar un espacio de conjuro con normalidad.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Conjuros de firma (Nivel 20)</h5>\r\n  <p>Elige dos conjuros de mago de nivel 3 de tu libro de conjuros como tus conjuros de firma. Siempre tienes esos conjuros preparados y no se cuentan entre el número de conjuros que tienes preparados. Puedes lanzar cada uno de ellos a nivel 3 sin gastar espacios de conjuro por descanso prolongado.</p>\r\n</div>\r\n', ''),
(10, 'Monje', 'Los monjes están unidos por su habilidad para utilizar mágicamente la energía que corre por sus cuerpos. Ya sea canalizada en una impactante demostración de proeza marcial o en el sutil enfoque en la habilidad defensiva y la velocidad, esta energía impulsa todo lo que el monje hace.', 'Cualquiera que sea su disciplina, los monjes están unidos por su habilidad para utilizar mágicamente la energía que corre por sus cuerpos. Ya sea canalizada en una impactante demostración de proeza marcial o en el sutil enfoque en la habilidad defensiva y la velocidad, esta energía impulsa todo lo que el monje hace.\r\n\r\n', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>Como monje, obtienes las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Artes marciales</h5>\r\n  <p>Cuando usas arma de monje y no llevas armadura ni escudo: Puedes usar Destreza en lugar de Fuerza para ataque y daño. Puedes usar el dado de daño desarmado en lugar del daño del arma. Tras atacar desarmado o con arma de monje, puedes usar una acción adicional para realizar un ataque desarmado.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Defensa sin armadura</h5>\r\n  <p>Mientras no lleves ni armadura ni escudo, tu CA es igual a 10 + tu modificador por Destreza + tu modificador por Sabiduría.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ki (Nivel 2)</h5>\r\n  <p>Tienes un número de puntos Ki igual a tu nivel de monje, que puedes gastar para activar rasgos de ki. Se recuperan tras un descanso. Si el rasgo requiere TS, la CD es 8 + bonificador de competencia + modificador de Sabiduría.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Defensa paciente (Nivel 2)</h5>\r\n  <p>Puedes gastar 1 punto de ki para hacer una acción de esquivar como acción adicional durante tu turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Paso del viento (Nivel 2)</h5>\r\n  <p>Puedes gastar 1 punto de ki para retirarte o esprintar como acción adicional. Tu distancia de salto se dobla ese turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ráfaga de golpes (Nivel 2)</h5>\r\n  <p>Tras realizar la acción de ataque, puedes gastar 1 punto de ki para hacer dos ataques desarmados como acción adicional.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Movimiento sin armadura (Nivel 2)</h5>\r\n  <p>Tu velocidad aumenta mientras no lleves armadura ni escudo. Este bono mejora con el nivel.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Desviar proyectiles (Nivel 3)</h5>\r\n  <p>Usa tu reacción para reducir el daño de un proyectil en 1d10 + Destreza + nivel de monje. Si reduces a 0, puedes gastar 1 punto de ki para devolverlo como ataque.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Caída lenta (Nivel 4)</h5>\r\n  <p>Usa tu reacción para reducir el daño por caída en 5 × tu nivel de monje.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>En niveles 4, 8, 12, 16 y 19, puedes subir un atributo en 2 puntos o dos en 1 (máx. 20).</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ataque adicional (Nivel 5)</h5>\r\n  <p>Puedes atacar dos veces al realizar la acción de ataque en tu turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Golpe aturdidor (Nivel 5)</h5>\r\n  <p>Cuando impactas en cuerpo a cuerpo, puedes gastar 1 punto de ki para intentar aturdir. TS de Constitución para resistir.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Impactos de ki (Nivel 6)</h5>\r\n  <p>Tus ataques desarmados cuentan como mágicos para superar resistencias o inmunidades.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Evasión (Nivel 7)</h5>\r\n  <p>Al hacer TS de Destreza contra efectos de área: sin daño con éxito, la mitad si fallas.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Quietud de la mente (Nivel 7)</h5>\r\n  <p>Usa tu acción para terminar efectos que te dejen hechizado o asustado.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Movimiento sin armadura mejorado (Nivel 9)</h5>\r\n  <p>Puedes moverte por paredes y líquidos sin caer mientras te mueves.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Pureza del cuerpo (Nivel 10)</h5>\r\n  <p>Eres inmune a enfermedades y veneno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lengua del sol y la luna (Nivel 13)</h5>\r\n  <p>Puedes comunicarte con cualquier criatura que tenga un idioma.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Alma de diamante (Nivel 14)</h5>\r\n  <p>Competencia en todas las TS. Si fallas una, puedes gastar 1 punto de ki para repetirla.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Cuerpo eterno (Nivel 15)</h5>\r\n  <p>No envejeces mágicamente. No necesitas comida ni agua.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Cuerpo vacío (Nivel 18)</h5>\r\n  <p>Puedes gastar 4 puntos de ki para volverte invisible 1 minuto y ganar resistencia a todo daño excepto fuerza.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Yo perfecto (Nivel 20)</h5>\r\n  <p>Cuando tires iniciativa y no tengas puntos de ki, recuperas 4 automáticamente.</p>\r\n</div>\r\n', ''),
(11, 'Paladin', 'Sean cuales sean sus orígenes y sus misiones, los paladines están unidos por sus juramentos para luchar en contra de las fuerzas del mal. El juramento de un paladín es un lazo muy poderoso. Es una fuente de poder que convierte a un devoto guerrero en un campeón bendecido.', 'Sean cuales sean sus orígenes y sus misiones, los paladines están unidos por sus juramentos para luchar en contra de las fuerzas del mal. El juramento de un paladín es un lazo muy poderoso. Es una fuente de poder que convierte a un devoto guerrero en un campeón bendecido.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>Como paladín, obtienes las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Sentidos divinos</h5>\r\n  <p>Como acción, puedes detectar, hasta el final de tu siguiente turno, dónde se encuentra cualquier celestial, infernal o no muerto a 60 pies que no esté completamente cubierto. Usos: 1 + modificador por Carisma por descanso largo.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Imponer las manos</h5>\r\n  <p>Tienes una reserva de curación igual a tu nivel de paladín × 5. Como acción, puedes tocar a una criatura y curarla usando esa reserva. Puedes gastar 5 PG de la reserva para curar una enfermedad o veneno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Castigo divino (Nivel 2)</h5>\r\n  <p>Al impactar con un arma cuerpo a cuerpo, puedes gastar un espacio de conjuro para infligir daño radiante adicional (2d8 + 1d8 por nivel superior, máx. 5d8). Más daño contra no muertos e infernales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Estilo de combate (Nivel 2)</h5>\r\n  <p>Adoptas un estilo de combate como especialidad. No puedes elegir el mismo más de una vez, incluso si obtienes esta opción nuevamente.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Lanzamiento de conjuros (Nivel 2)</h5>\r\n  <p>Usas Carisma para lanzar conjuros. Puedes preparar tantos conjuros como tu mod. de Carisma + la mitad de tu nivel de paladín. Requiere preparación y gasto de espacio de conjuro. Puedes usar un foco.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Canalizar divinidad (Nivel 3)</h5>\r\n  <p>Una vez por descanso corto o largo, puedes canalizar energía divina para activar efectos. Si requiere una tirada de salvación, la CD es la de tus conjuros de paladín.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Salud divina (Nivel 3)</h5>\r\n  <p>La magia divina en ti te vuelve inmune a las enfermedades.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>En niveles 4, 8, 12, 16 y 19, puedes aumentar una puntuación en 2 o dos en 1 punto (máx. 20).</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ataque adicional (Nivel 5)</h5>\r\n  <p>Puedes atacar dos veces cuando realices la acción de ataque en tu turno.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Aura de protección (Nivel 6)</h5>\r\n  <p>Tú y aliados cercanos ganáis un bonificador a TS igual a tu modificador por Carisma (mín. +1) mientras estés consciente.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Aura de valor (Nivel 10)</h5>\r\n  <p>Tú y aliados cercanos no podéis ser asustados mientras estés consciente.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Castigo divino mejorado (Nivel 11)</h5>\r\n  <p>Tus ataques cuerpo a cuerpo hacen 1d8 de daño radiante adicional. Se suma al Castigo divino si lo usas.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Toque purificador (Nivel 14)</h5>\r\n  <p>Usa tu acción para eliminar un conjuro que afecte a ti o a una criatura voluntaria que toques. Usos: tu modificador de Carisma por descanso largo (mín. 1).</p>\r\n</div>\r\n', ''),
(12, 'Picaro', 'Los pícaros confían sus habilidades, el sigilo y las vulnerabilidades de sus oponentes para lograr sacar ventaja. Tienen un don para encontrar la solución a cualquier problema, demostrando un ingenio y versatilidad, que es la piedra angular de cualquier buen grupo de aventureros.', 'Los pícaros confían sus habilidades, el sigilo y las vulnerabilidades de sus oponentes para lograr sacar ventaja en cualquier situación. Tienen un don para encontrar la solución a prácticamente cualquier problema, demostrando un ingenio y versatilidad, que es la piedra angular de cualquier buen grupo de aventureros.', '<div>\r\n  <h5>Competencias</h5>\r\n  <p>Como pícaro, obtienes las siguientes competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Competencias multiclase</h5>\r\n  <p>Cuando subes tu primer nivel en esta clase, si no es tu clase inicial, solo consigues algunas de las competencias iniciales.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Ataque furtivo</h5>\r\n  <p>Una vez por turno, puedes infligir daño adicional con un ataque si tienes ventaja en la tirada o si un aliado no incapacitado está a 5 pies del objetivo. Debe ser un ataque con un arma sutil o a distancia y no tener desventaja.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Jerga de ladrones</h5>\r\n  <p>Conoces una mezcla de códigos secretos y argot para comunicarte con otros pícaros. También puedes interpretar símbolos usados para esconder mensajes simples.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Pericia</h5>\r\n  <p>Elige dos competencias con habilidades (o una habilidad y herramientas de ladrón). Tu bonificador por competencia se duplica en pruebas que usen estas competencias.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Acción astuta (Nivel 2)</h5>\r\n  <p>En combate puedes usar una acción adicional cada turno para Correr, Destrabarte o Esconderte.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mejora de característica (Nivel 4)</h5>\r\n  <p>En los niveles 4, 8, 10, 12, 16 y 19 puedes aumentar una característica en 2 o dos características en 1 (máx. 20).</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Esquiva asombrosa (Nivel 5)</h5>\r\n  <p>Cuando un atacante que ves te impacta, puedes usar tu reacción para reducir el daño a la mitad.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Evasión (Nivel 7)</h5>\r\n  <p>Cuando haces una tirada de salvación de Destreza para recibir la mitad de daño, si aciertas no recibes daño, y si fallas, solo la mitad.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Talento fiable (Nivel 11)</h5>\r\n  <p>Cuando haces una prueba con competencia y sacas 9 o menos, puedes considerar que sacaste un 10.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Sentido ciego (Nivel 14)</h5>\r\n  <p>Si puedes oír, sabes dónde está cualquier criatura escondida o invisible a 10 pies o menos.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Mente resbaladiza (Nivel 15)</h5>\r\n  <p>Ganas competencia en tiradas de salvación de Sabiduría.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Elusivo (Nivel 18)</h5>\r\n  <p>Ninguna tirada de ataque tiene ventaja contra ti mientras no estés incapacitado.</p>\r\n</div>\r\n\r\n<div>\r\n  <h5>Golpe de suerte (Nivel 20)</h5>\r\n  <p>Una vez por descanso corto o largo, puedes convertir un fallo en un impacto. También puedes considerar un fallo en prueba de característica como un 20 natural.</p>\r\n</div>\r\n', '');

